class Node:
  def __init__(self, val, left=None, right=None):
    self.val = val
    self.left = left
    self.right = right

def kth_element(root, k):
  steps = 0
  res = None

  def visit(node):
    nonlocal steps, res
    if not node or res is not None:
      return
    visit(node.left)
    if steps == k:
      res = node.val
    steps += 1
    visit(node.right)

  visit(root)
  return res

