class Node {
  public int value;
  public Node left;
  public Node right;

  public Node(int value) {
    this.value = value;
    this.left = null;
    this.right = null;
  }

}

class KthElement {
  private int steps = 0;
  private int res = -1;

  private void visit(Node node, int k) {
    if (node == null || res != -1) {
      return;

    }
    visit(node.left, k);
    if (steps == k) {
      res = node.value;
    }
    steps++;
    visit(node.right, k);
  }

  public int solve(Node root, int k) {
    steps = 0;
    res = -1;
    visit(root, k);
    return res;
  }

}

